#!/usr/bin/env bash

write_manifests() {
  local version="$1"
  local package_dir
  mkdir -p \
    packages/tokenx \
    packages/tokenx-darwin-arm64 \
    packages/tokenx-linux-x64-gnu \
    packages/tokenx-win32-x64-msvc

  cat > Cargo.toml <<EOF_MANIFEST
[workspace.package]
version = "${version}"
EOF_MANIFEST

  cat > Cargo.lock <<EOF_LOCK
# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "anyhow"
version = "1.0.100"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "unchanged"

[[package]]
name = "tokenx"
version = "${version}"
dependencies = [
 "tokenx-engine",
]

[[package]]
name = "tokenx-engine"
version = "${version}"
EOF_LOCK

  cat > packages/tokenx/package.json <<EOF_MANIFEST
{
  "name": "@juya-ai/tokenx",
  "version": "${version}",
  "optionalDependencies": {
    "@juya-ai/tokenx-darwin-arm64": "${version}",
    "@juya-ai/tokenx-linux-x64-gnu": "${version}",
    "@juya-ai/tokenx-win32-x64-msvc": "${version}"
  }
}
EOF_MANIFEST

  for package_dir in \
    tokenx-darwin-arm64 \
    tokenx-linux-x64-gnu \
    tokenx-win32-x64-msvc; do
    cat > "packages/${package_dir}/package.json" <<EOF_MANIFEST
{
  "name": "@juya-ai/${package_dir}",
  "version": "${version}"
}
EOF_MANIFEST
  done

  cat > bun.lock <<EOF_LOCK
{
  "lockfileVersion": 1,
  "configVersion": 1,
  "workspaces": {
    "packages/tokenx": {
      "name": "@juya-ai/tokenx",
      "version": "${version}",
      "optionalDependencies": {
        "@juya-ai/tokenx-darwin-arm64": "${version}",
        "@juya-ai/tokenx-linux-x64-gnu": "${version}",
        "@juya-ai/tokenx-win32-x64-msvc": "${version}",
      },
    },
    "packages/tokenx-darwin-arm64": {
      "name": "@juya-ai/tokenx-darwin-arm64",
      "version": "${version}",
    },
    "packages/tokenx-linux-x64-gnu": {
      "name": "@juya-ai/tokenx-linux-x64-gnu",
      "version": "${version}",
    },
    "packages/tokenx-win32-x64-msvc": {
      "name": "@juya-ai/tokenx-win32-x64-msvc",
      "version": "${version}",
    },
  },
  "packages": {},
}
EOF_LOCK
}
